wiki_path = "/home/zhouhuijuan1987/wiki/youtube-video-research-wiki"

# 1. Count all new pages
result = terminal(f"find {wiki_path}/wiki -name '*.md' | wc -l")
total_pages = int(result["output"].strip())
print(f"📊 Total wiki pages: {total_pages}")

# 2. Check frontmatter completeness for new pages
result = terminal(f"find {wiki_path}/wiki -name '*.md' -newer {wiki_path}/TheSchema.md")
all_files = result["output"].strip().split("\n") if result["output"].strip() else []

print(f"📄 New pages: {len(all_files)}")

frontmatter_issues = []
content_issues = []
wikilink_count_issues = []

for f in all_files:
    content = read_file(f)["content"]

    # Check frontmatter fields
    required = ["title:", "type:", "tags:", "summary:", "sources:", "layer:"]
    missing = [r for r in required if f"\\n{r}" not in content.replace("\\n---\\n", "\\n---\\n")]

    # Simpler check: does the content start with --- and contain these fields?
    if not content.startswith("---"):
        frontmatter_issues.append(f"{f}: no frontmatter")
        continue

    # Find frontmatter block
    fm_end = content.find("\\n---\\n", 4)
    if fm_end == -1:
        frontmatter_issues.append(f"{f}: no closing ---")
        continue

    fm = content[4:fm_end]
    for field in required:
        if field not in fm:
            frontmatter_issues.append(f"{f}: missing {field}")

    # Check content length (approximate Chinese char count)
    body = content[fm_end+5:]
    # Count Chinese chars and total chars
    chinese_chars = sum(1 for c in body if '\u4e00' <= c <= '\u9fff')
    total_chars = len(body.strip())

    fname = f.split("/")[-1]
    ftype = f.split("/")[-2]

    if ftype in ("sources",):
        if total_chars < 400:
            content_issues.append(f"{fname}: only {total_chars} chars (need 400)")
        if chinese_chars < 200:
            content_issues.append(f"{fname}: only {chinese_chars} Chinese chars")
    elif ftype in ("entities", "concepts"):
        if total_chars < 200:
            content_issues.append(f"{fname}: only {total_chars} chars (need 200)")

    # Count wikilinks
    import re
    links = re.findall(r'\\[\\[([^|\\]]+)(?:\\|[^\\]]+)?\\]\\]', body)
    # Filter out mindmap cross-refs
    real_links = [l for l in links if "Instant-模型深度分析简报" not in l and "深度对比及技术趋势简报" not in l and "本地最强-Agent" not in l]
    if len(real_links) < 2:
        wikilink_count_issues.append(f"{fname}: only {len(real_links)} wikilinks (need 2)")

if frontmatter_issues:
    print(f"\\n❌ Frontmatter issues:")
    for i in frontmatter_issues: print(f"  - {i}")
else:
    print("\\n✅ All pages have complete frontmatter")

if content_issues:
    print(f"\\n❌ Content length issues:")
    for i in content_issues: print(f"  - {i}")
else:
    print("✅ All pages meet minimum content length")

if wikilink_count_issues:
    print(f"\\n❌ Wikilink count issues:")
    for i in wikilink_count_issues: print(f"  - {i}")
else:
    print("✅ All pages have at least 2 wikilinks")

# Check sources files exist
result = terminal(f"cd {wiki_path} && grep -rho '^sources:' wiki/sources/ --include='*.md' -A 10 | grep ' - raw/' | sed 's/^ *- //' | sort -u")
source_refs = [s.strip() for s in result["output"].strip().split("\\n") if s.strip()]
missing_sources = []
for ref in source_refs:
    result = terminal(f"test -f '{wiki_path}/{ref}' && echo 'exists' || echo 'missing'")
    if "missing" in result["output"]:
        missing_sources.append(ref)

if missing_sources:
    print(f"\\n❌ Missing source files:")
    for s in missing_sources: print(f"  - {s}")
else:
    print("✅ All sources field files exist in raw/")

print(f"\\n=== QUALITY CHECK SUMMARY ===")
print(f"Passed: {len(frontmatter_issues)==0}, {len(content_issues)==0}, {len(wikilink_count_issues)==0}, {len(missing_sources)==0}")
"}

