import os, re

wiki_path = "/home/zhouhuijuan1987/wiki/youtube-video-research-wiki/wiki"

# Find all .md files
result = terminal(f"find {wiki_path} -name '*.md'")
files = result["output"].strip().split("\n")

issues = []
for f in files:
    content = read_file(f)["content"]
    rel = os.path.relpath(f, wiki_path)
    parts = rel.split("/")
    ftype = parts[0] if len(parts) > 1 else "unknown"
    fname = parts[-1]

    # Get body (after frontmatter)
    body_start = content.find("\n---\n", 4)
    if body_start == -1:
        issues.append(f"{fname}: no closing frontmatter")
        continue
    body = content[body_start + 5:]

    # Count wikilinks (excluding mindmap cross-refs which are intentional per spec)
    links = re.findall(r'\[\[([^|\]]+)(?:\|[^\]]+)?\]\]', body)
    mindmap_patterns = ["Instant-模型深度分析简报", "深度对比及技术趋势简报", "本地最强-Agent"]
    real_links = [l for l in links if not any(p in l for p in mindmap_patterns)]

    chinese = sum(1 for c in body if '\u4e00' <= c <= '\u9fff')
    total = len(body.strip())

    if ftype == "sources":
        if total < 400:
            issues.append(f"{fname} (source): only {total} chars")
        if len(real_links) < 2:
            issues.append(f"{fname} (source): only {len(real_links)} wikilinks")
    elif ftype in ("entities", "concepts"):
        if total < 200:
            issues.append(f"{fname} ({ftype}): only {total} chars")
        if len(real_links) < 2:
            issues.append(f"{fname} ({ftype}): only {len(real_links)} wikilinks")
    elif ftype == "comparisons":
        if len(real_links) < 2:
            issues.append(f"{fname} (comparison): only {len(real_links)} wikilinks")
    elif ftype == "overview":
        if total < 400:
            issues.append(f"{fname} (overview): only {total} chars")
        if len(real_links) < 2:
            issues.append(f"{fname} (overview): only {len(real_links)} wikilinks")

if issues:
    print("❌ Quality issues found:")
    for i in issues:
        print(f"  - {i}")
else:
    print("✅ ALL QUALITY CHECKS PASSED!")
    print(f"  - {len(files)} pages checked")
    print(f"  - All frontmatter complete")
    print(f"  - All meet min content length")
    print(f"  - All have ≥2 wikilinks")
"}
